    }
  ],
  "name": "NeuroRehabPREM",
  "title": "Patient Reported Experience Measure – Neurorehabilitation",
  "status": "active",
  "date": "2025-08-19",
  "publisher": "NeuroRehab Research Unit",
  "description": "Open-ended PREM questionnaire for neurorehabilitation, structured along PaRIS framework domains.",
  "purpose": "To capture patient-reported experiences in neurorehabilitation for NLP-based sentiment and topic analysis.",
  "copyright": "© Victor Hüni, 2025",
  "approvalDate": "2025-08-01",
  "effectivePeriod": {
    "start": "2025-08-19"
  },
  "text": {
    "status": "generated",
    "div": "<div xmlns='http://www.w3.org/1999/xhtml'><p><b>Neurorehabilitation PREM Questionnaire</b> – Open-ended questions aligned with PaRIS domains plus Net Promoter Score</p></div>"
  },
  "subjectType": ["Patient"],
  "useContext": [
    {
      "code": {
        "system": "http://terminology.hl7.org/CodeSystem/usage-context-type",
        "code": "focus"
      },
      "valueCodeableConcept": {
        "text": "Neurorehabilitation"
      }
    }
  ],
  "meta": {
    "profile": ["http://hl7.org/fhir/StructureDefinition/Questionnaire"],
    "tag": [
      {
        "system": "http://example.org/fhir/tags",
        "code": "prem",
        "display": "PREM"
      }
    ]
  },
  "code": [
    {
      "system": "http://example.org/fhir/codesystem/prem",
      "code": "NeuroRehabPREM",
      "display": "Neurorehabilitation PREM Questionnaire"
    }
  ],
  "item": [
    {
      "linkId": "ppnq-q1",
      "text": "Please describe your experience accessing neurorehabilitation services or contacting your care team when you needed support.",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q01" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "access" }
      ]
    },
    {
      "linkId": "ppnq-q2",
      "text": "In what ways did the rehabilitation program address (or not address) all of your needs (physical, cognitive, emotional, social)?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q02" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "comprehensiveness" }
      ]
    },
    {
      "linkId": "ppnq-q3a",
      "text": "How did the consistency of working with the same rehabilitation professionals impact your experience?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q03a" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "continuity" }
      ]
    },
    {
      "linkId": "ppnq-q3b",
      "text": "Can you describe how well your different rehabilitation professionals (therapists, doctors, nurses, psychologists) shared information and worked together over time to support your recovery?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q03b" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "continuity" }
      ]
    },
    {
      "linkId": "ppnq-q4",
      "text": "Can you describe how well your different specialists (therapists, doctors, nurses, psychologists) worked together in your rehabilitation?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q04" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "coordination" }
      ]
    },
    {
      "linkId": "ppnq-q5",
      "text": "Please share any experiences where you felt safe or unsafe during your rehabilitation (e.g., exercises, therapies, medication).",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q05" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "patient-safety" }
      ]
    },
    {
      "linkId": "ppnq-q6",
      "text": "How well did the rehabilitation team listen to your personal goals, preferences, and values?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q06" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "person-centredness" }
      ]
    },
    {
      "linkId": "ppnq-q7",
      "text": "How did the rehabilitation team help (or not help) you develop skills and strategies to manage your condition in daily life?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q07" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "self-management-support" }
      ]
    },
    {
      "linkId": "ppnq-q8",
      "text": "What made you trust (or not trust) your rehabilitation team?",
      "type": "string",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q08" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "trust" }
      ]
    },
    {
      "linkId": "ppnq-q9",
      "text": "On a scale from 0 to 10, how likely are you to recommend this rehabilitation program to a friend or family member in need of similar care?",
      "type": "choice",
      "required": true,
      "answerValueSet": "http://example.org/fhir/ValueSet/nps-0-10",
      "code": [
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-neurorehab-items", "code": "PPNQ-Q09" },
        { "system": "http://example.org/fhir/CodeSystem/prem-paris-domain", "code": "overall-perceived-quality" }
      ]
    },
    {
      "linkId": "ppnq-q9-text",
      "text": "What is the main reason for your score?",
      "type": "string",
      "enableWhen": [
        {
          "question": "ppnq-q9",
          "operator": "exists",
          "answerBoolean": true
        }
      ]
    }
  ]
}

